"600\" fill=\"currentColor\">1975</text><rect x=\"350\" y=\"52.0\" width=\"44\" height=\"148.0\" rx=\"4\" fill=\"#3B82F6\" fill-opacity=\"0.7\"/><text x=\"372.0\" y=\"45.0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#3B82F6\">74 %</text><text x=\"372.0\" y=\"218.0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\" fill=\"currentColor\">1990</text><rect x=\"418\" y=\"40.0\" width=\"44\" height=\"160.0\" rx=\"4\" fill=\"#3B82F6\" fill-opacity=\"0.8\"/><text x=\"440.0\" y=\"33.0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"800\" fill=\"#3B82F6\">80 %</text><text x=\"440.0\" y=\"218.0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\" fill=\"currentColor\">auj.</text></svg>",
